// FUNCTIONS //

/**
* Copies logical values in bounded blocks, matching both dependency backends.
* @private
* @param {integer} n - count
* @param {Float64Array} x - input
* @param {integer} sx - input stride
* @param {integer} ox - input offset
* @param {Float64Array} y - output
* @param {integer} sy - output stride
* @param {integer} oy - output offset
* @returns {void}
*/
function copy(n, x, sx, ox, y, sy, oy) {
	var m;
	var i;
	for (i = 0; (i < n); i += m) {
		m = min(7, (n - i));
		dcopy(m, x, sx, (ox + (i * sx)), y, sy, (oy + (i * sy)));
	}
}
/**
* Finds the first logical maximum without allocating a reversed copy.
* @private
* @param {integer} n - count
* @param {Float64Array} x - vector
* @param {integer} sx - stride
* @param {integer} ox - offset
* @returns {integer} zero-based ordinal
*/
function firstMax(n, x, sx, ox) {
	var maximum;
	var index;
	var value;
	var i;
	if ((n < 1)) {
		return -1;
	}
	if ((n === 1)) {
		return 0;
	}
	maximum = abs(x[ox]);
	index = 0;
	for (i = 1; (i < n); i++) {
		value = abs(x[(ox + (i * sx))]);
		if ((value > maximum)) {
			maximum = value;
			index = i;
		}
	}
	return index;
}
/**
* Applies exactly the pinned unconditional NT GEMV accumulation order.
* @private
* @param {integer} m - rows
* @param {integer} n - columns
* @param {Float64Array} a - matrix
* @param {integer} r - row stride
* @param {integer} c - column stride
* @param {integer} o - matrix offset
* @param {Float64Array} x - input vector
* @param {integer} sx - input stride
* @param {integer} ox - input offset
* @param {Float64Array} y - updated vector
* @param {integer} sy - output stride
* @param {integer} oy - output offset
* @returns {void}
*/
